-- Lane A figures for ap_statistics: generated by build_load_sql.py, do not hand-edit.
-- 3 figures across 1 families, from scripts/lane-a-pilot/specs.json.
-- Entries are resolved by natural key, so this file is portable between environments.

begin;

-- 1. The renderer families this batch INTRODUCES (DECISION-0115: a row, not a CHECK).
-- Reused without introducing: none
insert into app.figure_families (family_key, title, summary, renderer_note)
values ('density_curve', 'Probability density curves', 'Normal and chi-square densities with the area under them shaded: the normal curve, the standard normal, the empirical rule''s nested bands, probability as an area, a critical value bounding the middle C%, the tail a p-value lives in, and the chi-square family''s skew. Chi-square is drawn for EVEN degrees of freedom only, so its gamma is an exact factorial and the two renderers agree byte for byte. What a shaded band claims is checked against the integral, not trusted to the fill.', 'scripts/lane-a-pilot/render.py; the app''s figure renderer')
on conflict (family_key) do nothing;

-- 2. The figures.
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('stats-mean-median-right', 'ap_statistics', 'density_curve', 'Skewed right: the mean is above the median', 'Mean above median', 'The long right tail pulls the mean toward larger values (figure 1 of 3)', 'A right-skewed density curve with its median and mean marked.', 'A right-skewed density curve with two dashed vertical lines. The median is the left line, at about 3.4, and the mean is the right line, at about 4.0, so the mean is larger than the median. The long right tail pulls the mean toward larger values. Illustrative data.', 'value of the variable', 'relative likelihood (density)', 'In a right-skewed distribution the mean is usually larger than the median.', true, null, '["Mean above the median", "Skewed right"]'::jsonb, '{"x_range": [0.0, 16.0], "x_ticks": [[0.0, "0"], [4.0, "4"], [8.0, "8"], [12.0, "12"], [16.0, "16"]], "curves": [{"kind": "chi_square", "df": 4, "style": "solid"}], "vlines": [{"x": 3.356, "label": null, "caption": null}, {"x": 4.0, "label": null, "caption": null}], "texts": [{"x": 4.4, "y": 0.205, "label": "median (left line)", "anchor": "start"}, {"x": 4.4, "y": 0.175, "label": "mean (right line)", "anchor": "start"}], "skew_checks": [{"curve": 0, "direction": "right"}], "stat_line_checks": [{"curve": 0}]}'::jsonb, null, null, 'published', 'cramapple-authored; batch=stats-next3-figures-2026-10-15', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('stats-mean-median-left', 'ap_statistics', 'density_curve', 'Skewed left: the mean is below the median', 'Mean below median', 'The long left tail pulls the mean toward smaller values (figure 2 of 3)', 'A left-skewed density curve with its mean and median marked.', 'A left-skewed density curve with two dashed vertical lines. The mean is the left line, at about 12.0, and the median is the right line, at about 12.6, so the mean is smaller than the median. The long left tail pulls the mean toward smaller values. Illustrative data.', 'value of the variable', 'relative likelihood (density)', 'In a left-skewed distribution the mean is usually smaller than the median.', true, null, '["Mean below the median", "Skewed left"]'::jsonb, '{"x_range": [0.0, 16.0], "x_ticks": [[0.0, "0"], [4.0, "4"], [8.0, "8"], [12.0, "12"], [16.0, "16"]], "curves": [{"kind": "chi_square", "df": 4, "mirror_about": 16, "style": "solid"}], "vlines": [{"x": 12.0, "label": null, "caption": null}, {"x": 12.644, "label": null, "caption": null}], "texts": [{"x": 11.6, "y": 0.205, "label": "mean (left line)", "anchor": "end"}, {"x": 11.6, "y": 0.175, "label": "median (right line)", "anchor": "end"}], "skew_checks": [{"curve": 0, "direction": "left"}], "stat_line_checks": [{"curve": 0}]}'::jsonb, null, null, 'published', 'cramapple-authored; batch=stats-next3-figures-2026-10-15', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('stats-mean-median-symmetric', 'ap_statistics', 'density_curve', 'Relatively symmetric: the mean and median are close', 'Mean close to median', 'With no long tail the mean and median nearly coincide (figure 3 of 3)', 'A bell-shaped density curve whose mean and median are at the same place.', 'A bell-shaped density curve with one dashed vertical line through the centre, at about 8. The mean and the median are at the same place, so they are close together. With no long tail pulling either way, the distribution is relatively symmetric. Illustrative data.', 'value of the variable', 'relative likelihood (density)', 'In a relatively symmetric distribution the mean and median are close.', true, null, '["Mean and median close together", "Relatively symmetric"]'::jsonb, '{"x_range": [0.0, 16.0], "x_ticks": [[0.0, "0"], [4.0, "4"], [8.0, "8"], [12.0, "12"], [16.0, "16"]], "curves": [{"kind": "normal", "mu": 8.0, "sigma": 2.7, "style": "solid"}], "vlines": [{"x": 8.0, "label": "mean = median", "caption": null}], "skew_checks": [{"curve": 0, "direction": "none"}], "stat_line_checks": [{"curve": 0}]}'::jsonb, null, null, 'published', 'cramapple-authored; batch=stats-next3-figures-2026-10-15', now())
on conflict (figure_id) do nothing;

-- 3. Where each figure is shown, resolved by natural key (protocol §6).
insert into app.figure_uses (figure_id, reference_entry_id, role)
select 'stats-mean-median-right', e.reference_entry_id, 'primary'
  from app.unit_reference_entries e
 where e.subject_key = 'ap_statistics' and e.kind = 'convention'
   and e.title = 'Mean vs. median under skew' and e.status = 'published'
on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;
insert into app.figure_uses (figure_id, reference_entry_id, role)
select 'stats-mean-median-left', e.reference_entry_id, 'primary'
  from app.unit_reference_entries e
 where e.subject_key = 'ap_statistics' and e.kind = 'convention'
   and e.title = 'Mean vs. median under skew' and e.status = 'published'
on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;
insert into app.figure_uses (figure_id, reference_entry_id, role)
select 'stats-mean-median-symmetric', e.reference_entry_id, 'primary'
  from app.unit_reference_entries e
 where e.subject_key = 'ap_statistics' and e.kind = 'convention'
   and e.title = 'Mean vs. median under skew' and e.status = 'published'
on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;

-- 4. Guards: no dead figure, and every entry this batch covers got its figures.
do $$
declare v_dead text; v_n int;
begin
  select string_agg(f.figure_id, ', ') into v_dead
    from app.figures f left join app.figure_uses u on u.figure_id = f.figure_id
   where f.figure_id in ('stats-mean-median-right', 'stats-mean-median-left', 'stats-mean-median-symmetric') and u.figure_id is null;
  if v_dead is not null then
    raise exception 'figures with no use, refusing to ship dead rows: %', v_dead;
  end if;
  select count(*) into v_n from app.figures where figure_id in ('stats-mean-median-right', 'stats-mean-median-left', 'stats-mean-median-symmetric');
  if v_n <> 3 then
    raise exception 'expected 3 figures, found %', v_n;
  end if;
end $$;

commit;
